package servicio;
import java.math.BigDecimal;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.HexFormat;import dao.*;import negocio.*;import pagos.*;
public class WebhookMercadoPagoService {private final OrdenPagoDAO ordenes;private final PasarelaPagoOnline pasarela;private final AcreditacionOrdenPagoTransaccionalService acreditacion;public WebhookMercadoPagoService(OrdenPagoDAO o,PasarelaPagoOnline p,AcreditacionOrdenPagoTransaccionalService a){if(o==null||p==null||a==null)throw new IllegalArgumentException("Las dependencias son obligatorias.");ordenes=o;pasarela=p;acreditacion=a;}public Resultado procesar(String pagoId,String payload){PagoExterno pago=pasarela.consultarPago(pagoId);if(pago==null||pago.pagoId()==null)throw new IllegalArgumentException("El pago externo no existe.");OrdenPago orden=ordenes.buscarPorPagoExterno(ProveedorPago.MERCADO_PAGO,pago.pagoId());if(orden==null)orden=ordenes.buscarPorReferencia(ProveedorPago.MERCADO_PAGO,pago.referencia());if(orden==null)throw new ConflictoPagoException("No existe una orden asociada al pago.");validarFinanzas(orden,pago);ordenes.asociarPagoExterno(orden.getId(),pago.pagoId());if(!pago.aprobado())return new Resultado(false,false,pago.estado());EventoPago e=new EventoPago();e.setOrdenPagoId(orden.getId());e.setProveedor(ProveedorPago.MERCADO_PAGO);e.setEventoExternoId("payment:"+pago.pagoId()+":"+pago.estado());e.setTipo("payment.updated");e.setFirmaValida(true);e.setPayloadHash(hash(payload));e.setPayloadJson(payload);boolean procesado=acreditacion.procesarAprobacion(e,pago.pagoId());return new Resultado(true,procesado,pago.estado());}private void validarFinanzas(OrdenPago o,PagoExterno p){if(o.getProveedor()!=ProveedorPago.MERCADO_PAGO)throw new ConflictoPagoException("El proveedor no coincide.");if(p.referencia()==null||!p.referencia().equals(o.getReferenciaExterna()))throw new ConflictoPagoException("La referencia no coincide.");if(p.importe()==null||p.importe().compareTo(o.getImporte())!=0)throw new ConflictoPagoException("El importe no coincide.");if(p.moneda()==null||!p.moneda().equalsIgnoreCase(o.getMoneda()))throw new ConflictoPagoException("La moneda no coincide.");}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((v==null?"":v).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public record Resultado(boolean aprobado,boolean procesado,String estadoExterno){}public static class ConflictoPagoException extends RuntimeException{public ConflictoPagoException(String m){super(m);}}}
